export function getProductColorScheme(productId: string): ProductColorScheme {
  const normalized = (productId || "").toLowerCase().trim();
  if (PRODUCT_COLOR_SCHEMES[normalized]) {
    return PRODUCT_COLOR_SCHEMES[normalized];
  }
  // Fallback defaults
  return {
    productId: normalized,
    category: "general",
    isMultiColor: false,
    colorMode: "single",
    primaryColor: "#B39982",
    accentColor: "#B39982",
    baseColor: "#D4AF37",
    baseFinish: "Golden",
    primaryName: "Primary Finish",
    accentName: "Accent Finish"
  };
}